/* Freezers ESPORT team hub. GitHub credentials live in memory only. */
const API_BASE=String(window.FREEZERS_API_URL||'').replace(/\/$/,'');
const DATA_FILES={events:'calendar.json',roster:'roster.json',playbook:'playbook.json',rsvps:'rsvps.json',attendance:'attendance.json',excuses:'excuses.json',admins:'admins.json',staff:'staff.json',logs:'activity.json'};
const DEFAULTS={events:[],roster:{main:[],reserve:[],academy:[]},playbook:{entries:[],maps:[]},rsvps:{},attendance:{},excuses:{},admins:[],staff:[],logs:[]};
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function getCookie(name){const value=document.cookie.split('; ').find(x=>x.startsWith(encodeURIComponent(name)+'='))?.split('=').slice(1).join('=')||'';try{return decodeURIComponent(value)}catch{return value}}
function setCookie(name,value,days=180){document.cookie=`${encodeURIComponent(name)}=${encodeURIComponent(value)}; Max-Age=${days*86400}; Path=/; SameSite=Lax${location.protocol==='https:'?'; Secure':''}`}
const state={...structuredClone(DEFAULTS),page:'dashboard',adminTab:'events',calendarView:getCookie('freezers_calendar_view')||'month',calendarDate:new Date(),map:'all',search:'',points:120,config:{},token:'',apiSession:'',permissions:{},github:false,authenticated:false,currentUser:null,userRole:null,username:getCookie('freezers_user')||'FILAS'};
const key='freezers_data_v1', overrides=API_BASE?{}:JSON.parse(localStorage.getItem(key)||localStorage.getItem('gg_overrides_v1')||'{}');if(API_BASE){for(const oldKey of [key,'gg_overrides_v1','freezers_config','gg_config'])localStorage.removeItem(oldKey)}
function saveLocal(){const o={};for(const k of Object.keys(DATA_FILES))o[k]=state[k];localStorage.setItem(key,JSON.stringify(o))}
function toast(msg,type='success'){const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;$('#toastRegion').append(el);setTimeout(()=>el.remove(),3400)}
function log(message,icon='↗'){state.logs.unshift({message,icon,at:new Date().toISOString()});state.logs=state.logs.slice(0,60);saveLocal();renderLogs();if(state.github)githubWrite('logs').catch(e=>toast('Zápis logu na GitHub selhal: '+e.message,'error'))}
function fmtDate(value,opts={weekday:'short',day:'numeric',month:'short'}){return new Intl.DateTimeFormat('cs-CZ',opts).format(new Date(value))}
function monthName(d){return new Intl.DateTimeFormat('cs-CZ',{month:'long',year:'numeric'}).format(d)}
function initials(name){return String(name||'?').trim().slice(0,2).toUpperCase()}
function allPlayers(){return Object.values(state.roster||{}).flat().filter(p=>p&&p.type!=='empty'&&p.name)}
function userByAlias(alias){const a=String(alias).toLowerCase();return allPlayers().find(p=>[p.name,p.faceit?.split('/').pop()].filter(Boolean).some(x=>String(x).toLowerCase()===a))?.name||alias}
function counts(){const players=allPlayers(),absences={};Object.entries(state.attendance||{}).forEach(([event,rows])=>Object.entries(rows||{}).forEach(([user,status])=>{if(status==='unexcused'){const n=userByAlias(user);absences[n]=(absences[n]||0)+1}}));return{players,absences}}
function eventsSorted(){return [...(state.events||[])].sort((a,b)=>new Date(a.date)-new Date(b.date))}
function futureEvents(){return eventsSorted().filter(e=>new Date(e.date)>=new Date(new Date().setHours(0,0,0,0)))}
function typeName(t){return({training:'Trénink',scrim:'Zápas / Scrim',tournament:'Turnaj',meeting:'Meeting'})[t]||t||'Událost'}
function eventType(t){return `<span class="event-type ${esc(t||'')}">${esc(typeName(t))}</span>`}
function eventRow(e){let d=new Date(e.date);return `<div class="event-row" data-event="${esc(e.id)}"><div class="date-block"><b>${d.toLocaleDateString('cs-CZ',{day:'2-digit'})}</b><small>${d.toLocaleDateString('cs-CZ',{month:'short'})}</small></div><div><h4>${esc(e.title)}</h4><p>${d.toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit'})} · ${esc(e.location||'Online / týmový server')}</p></div>${eventType(e.type)}</div>`}
function playerRow(p,absences={},mini=false){const n=absences[p.name]||0,alert=n>=5;return `<div class="player-row ${alert?'alert':''}"><span class="player-avatar">${esc(initials(p.name))}</span><span class="player-info"><b>${esc(p.name)}</b><small>${esc(p.role||typeName(p.type))}${n?` · <span class="${alert?'danger-number':''}">${n}× absence</span>`:''}</small></span>${alert?'<span class="absence-pill">⚠ 5+</span>':`<span class="player-role">${esc(p.type==='captain'?'Kapitán':p.type==='trial'?'Trial':'Aktivní')}</span>`}</div>`}
function pageHeading(kicker,title,sub,action=''){return `<div class="section-head"><div><div class="section-kicker">${kicker}</div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action?`<div class="section-actions">${action}</div>`:''}</div>`}
function renderDashboard(){const {players,absences}=counts(), ev=futureEvents(),next=ev[0];return `<section class="hero"><div class="hero-content"><span class="hero-tag">OFFICIAL TEAM HUB · SEASON 2026</span><h1>Každý round.<br><span>Jeden tým.</span></h1><p>Vše pro váš další level. Tréninky, sestava i taktiky na jednom místě.</p></div><div class="hero-foot"><img src="assets/logo.png" alt=""> FREEZERS ESPORT</div></section>
${pageHeading('MATCH CENTER','Tým v číslech','Základní přehled týmu Freezers ESPORT.')}
<div class="stats-grid"><div class="stat-card"><span class="stat-icon">♟</span><div class="stat-label">AKTIVNÍ HRÁČI</div><div class="stat-value blue">${players.length.toString().padStart(2,'0')}</div><div class="stat-note">napříč sestavami</div></div><div class="stat-card"><span class="stat-icon">▦</span><div class="stat-label">NADCHÁZEJÍCÍ AKCE</div><div class="stat-value">${ev.length.toString().padStart(2,'0')}</div><div class="stat-note">${next?`další už ${fmtDate(next.date,{day:'numeric',month:'long'})}`:'kalendář je volný'}</div></div><div class="stat-card"><span class="stat-icon">◈</span><div class="stat-label">TAKTIKY V PLAYBOOKU</div><div class="stat-value green">${state.playbook.entries?.length||0}</div><div class="stat-note">${new Set(state.playbook.entries?.map(x=>x.map)).size} aktivní mapy</div></div><div class="stat-card"><span class="stat-icon">⚑</span><div class="stat-label">BODY AKTIVITY</div><div class="stat-value orange">${state.points}</div><div class="stat-note">váš týmový balance</div></div></div>
<div class="content-grid"><section class="panel"><div class="panel-head"><div><h3>Nejbližší akce</h3><p>Co vás čeká v následujících dnech.</p></div><a class="text-link" href="#calendar">CELÝ KALENDÁŘ →</a></div><div class="event-list">${ev.length?ev.slice(0,4).map(eventRow).join(''):'<div class="empty"><b>Žádné nadcházející akce</b>Přidejte trénink nebo zápas do kalendáře.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h3>Main roster</h3><p>Aktuální sestava Freezers ESPORT.</p></div><a class="text-link" href="#roster">SOUPISKA →</a></div><div class="roster-mini">${(state.roster.main||[]).slice(0,5).map(p=>playerRow(p,absences,true)).join('')||'<div class="empty">Sestava je prázdná.</div>'}</div></section></div>
<section class="panel" style="margin-top:14px"><div class="partner-strip"><span class="partner-label">DÍKY NAŠIM PARTNERŮM</span><img src="assets/partner-logos/ceska-asociace-esportu-1789898582762.png" alt="Česká asociace esportu"><img src="assets/partner-logos/fionshop-1789901151541.avif" alt="FionShop"><img src="assets/partner-logos/slovenska-asociacia-elektronickych-sportov-1789901183905.png" alt="Slovenská asociácia elektronických športov"></div></section>`}
function renderCalendar(){if(!state.authenticated)return restrictedPrompt('kalendář');const date=state.calendarDate,events=eventsSorted();const monthStart=new Date(date.getFullYear(),date.getMonth(),1),gridStart=new Date(monthStart);gridStart.setDate(1-((gridStart.getDay()+6)%7));const today=new Date();let days=42;if(state.calendarView==='week')days=7;if(state.calendarView==='day')days=1;let start=new Date(gridStart);if(state.calendarView==='week'){start=new Date(date);start.setDate(date.getDate()-((date.getDay()+6)%7))}if(state.calendarView==='day')start=new Date(date);const cells=Array.from({length:days},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const iso=d.toISOString().slice(0,10),dayEvents=events.filter(e=>new Date(e.date).toISOString().slice(0,10)===iso);return `<div class="day-cell ${d.getMonth()===date.getMonth()?'':'muted-day'}" data-day="${iso}"><div class="day-number ${d.toDateString()===today.toDateString()?'today':''}"><span>${d.getDate()}</span>${dayEvents.length?`<span>${dayEvents.length} akc.</span>`:''}</div>${dayEvents.slice(0,3).map(e=>`<div class="cal-event ${esc(e.type||'')}" data-event="${esc(e.id)}">${d.toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit'})} ${esc(e.title)}</div>`).join('')}</div>`}).join('');const next=events.filter(e=>new Date(e.date)>=new Date(new Date().setHours(0,0,0,0))).slice(0,9);return `${pageHeading('PLÁNOVÁNÍ TÝMU','Kalendář','Tréninky, zápasy a turnaje na jednom místě.',`${hasPermission('events')?'<button class="btn btn-primary" data-action="add-event">＋ Přidat událost</button>':''}`)}<div class="section-head" style="margin-top:0;align-items:center"><div class="calendar-toolbar"><button class="btn btn-small" data-action="cal-prev">←</button><h2 class="month-title">${esc(monthName(date))}</h2><button class="btn btn-small" data-action="cal-next">→</button><button class="btn btn-small btn-ghost" data-action="cal-today">Dnes</button></div><div class="view-switch">${['month','week','day'].map(v=>`<button data-view="${v}" class="${state.calendarView===v?'active':''}">${({month:'Měsíc',week:'Týden',day:'Den'})[v]}</button>`).join('')}</div></div><div class="calendar-layout"><div class="calendar-box"><div class="calendar-head">${['PO','ÚT','ST','ČT','PÁ','SO','NE'].map(x=>`<div>${state.calendarView==='day'?'ČAS':x}</div>`).join('')}</div><div class="calendar-grid">${cells}</div></div><aside class="calendar-side"><section class="panel"><div class="panel-head"><div><h3>Nejbližší akce</h3><p>${next.length} naplánovaných</p></div></div><div class="date-list">${next.length?next.map(eventRow).join(''):'<div class="empty">Nic v plánu.</div>'}</div></section><section class="panel"><div class="panel-head"><h3>Typy akcí</h3></div><div class="record-line"><span>Trénink</span>${eventType('training')}</div><div class="record-line"><span>Scrim / zápas</span>${eventType('scrim')}</div><div class="record-line"><span>Turnaj</span>${eventType('tournament')}</div></section></aside></div>`}
function renderPlaybook(){if(!state.authenticated)return restrictedPrompt('playbook');const maps=state.playbook.maps||[], entries=state.playbook.entries||[], shown=entries.filter(e=>(state.map==='all'||e.map===state.map)&&(!state.search||`${e.title} ${e.map} ${e.description}`.toLowerCase().includes(state.search.toLowerCase())));return `${pageHeading('TAKTICKÁ PŘÍPRAVA','Playbook','Callouty a setupy připravené na další mapu.',`${hasPermission('playbook')?'<button class="btn btn-primary" data-action="add-strat">＋ Přidat taktiku</button>':''}`)}<div class="field" style="max-width:320px;margin-bottom:12px"><input id="stratSearch" type="search" value="${esc(state.search)}" placeholder="⌕  Hledat taktiku, mapu nebo callout…"></div><div class="map-grid"><div class="map-card ${state.map==='all'?'active':''}" data-map="all"><img src="assets/mountain.png" alt="Všechny mapy"><b>Všechny mapy</b><small>${entries.length} TAKTIK</small></div>${maps.map(m=>`<div class="map-card ${state.map===m.name?'active':''}" data-map="${esc(m.name)}"><img src="${esc(mapImage(m))}" alt="${esc(m.name)}"><b>${esc(m.name)}</b><small>${entries.filter(e=>e.map===m.name).length} TAKTIK</small></div>`).join('')}</div><div class="playbook-grid">${shown.map(e=>`<article class="strat-card"><div class="strat-top"><h3>${esc(e.title)}</h3>${eventType('scrim')}</div>${e.videoLink&&youtubeEmbed(e.videoLink)?`<div class="strat-video"><iframe src="${esc(youtubeEmbed(e.videoLink))}" title="${esc(e.title)} – video" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div>`:''}<p class="strat-caption">${esc(e.description||'Video ukázka týmové taktiky.')}</p><div class="strat-foot"><span>${esc(e.map)} · ${e.addedAt?fmtDate(e.addedAt,{day:'numeric',month:'short',year:'numeric'}):'týmový setup'}</span>${e.videoLink?`<a href="${esc(e.videoLink)}" target="_blank" rel="noopener">▶ Zobrazit video</a>`:''}</div></article>`).join('')||'<div class="empty panel" style="grid-column:1/-1">Žádné taktiky tomuto filtru neodpovídají.</div>'}</div>`}
function youtubeEmbed(raw){try{const u=new URL(raw);let id="";if(u.hostname==="youtu.be")id=u.pathname.split("/").filter(Boolean)[0]||"";else if(["youtube.com","www.youtube.com","m.youtube.com","youtube-nocookie.com","www.youtube-nocookie.com"].includes(u.hostname)){if(u.pathname==="/watch")id=u.searchParams.get("v")||"";else if(/^\/(embed|shorts)\//.test(u.pathname))id=u.pathname.split("/")[2]||""}return /^[A-Za-z0-9_-]{11}$/.test(id)?`https://www.youtube-nocookie.com/embed/${id}`:""}catch{return ""}}
function mapImage(m){const file=(m.image||'').split('/').pop();return `assets/playbook-maps/${encodeURIComponent(file)}`}
function renderRosterGroup(group,items,absences){const labels={main:['MAIN ROSTER','HLAVNÍ SESTAVA'],reserve:['RESERVE MAIN','REZERVA'],academy:['ACADEMY','AKADEMIE'],'academy-reserve':['ACADEMY · RESERVE','REZERVA AKADEMIE']},[kicker,title]=labels[group]||[group.toUpperCase(),group];return `<section class="panel"><div class="panel-head"><div><span class="section-kicker">${kicker}</span><h3 class="group-head">${title}<span>${items.filter(p=>p?.name&&p.type!=='empty').length} HRÁČŮ</span></h3></div></div><div class="players-grid">${items.map(p=>{if(!p||p.type==='empty')return `<a class="vacancy-card" href="https://discord.gg/Ntcz76sXkP" target="_blank" rel="noopener"><span class="vacancy-plus">＋</span><span><b>Volné místo</b><small>Přidej se k týmu na Discordu ↗</small></span></a>`;const n=absences[p.name]||0;return `<div class="player-card ${n>=5?'alert':''}"><span class="player-avatar">${esc(initials(p.name))}</span><span class="player-info"><b>${esc(p.name)}</b><small>${esc(p.role||'Člen týmu')}</small></span>${p.faceit?`<a class="text-link" href="${esc(p.faceit)}" target="_blank" rel="noopener">FACEIT ↗</a>`:''}${n>=5?`<span class="absence-pill">⚠ ${n}×</span>`:''}</div>`}).join('')||'<div class="empty">Zatím zde nejsou žádní hráči.</div>'}</div></section>`}
function renderRoster(){const {absences}=counts();return `${pageHeading('SESTAVY FREEZERS','Roster','Čtyři úrovně, jeden tým. Volná místa jsou otevřená — klikni a přidej se do komunity.') }<div class="roster-groups">${Object.entries(state.roster||{}).map(([group,players])=>renderRosterGroup(group,players||[],absences)).join('')}</div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><span class="section-kicker">PŘIDEJ SE K FREEZERS</span><h3 class="group-head">Hledáme nové tváře</h3><p>Napiš nám na Discordu a představ se týmu.</p></div><a class="btn btn-primary" href="https://discord.gg/Ntcz76sXkP" target="_blank" rel="noopener">Připojit se na Discord ↗</a></div></section>`}function renderHazard(){const upcoming=futureEvents();return `${pageHeading('TEAM PREDICTIONS','Tipovačka','Přátelské predikce a týmové body. Bez skutečných peněz.') }<div class="hazard-hero"><div><span class="eyebrow">TVŮJ TEAM BALANCE</span><div class="points">${state.points}<small>GLOCK COINS · INTERNÍ BODY</small></div></div><span style="font-size:42px">♧</span></div><div class="section-head"><div><div class="section-kicker">DALŠÍ MATCHDAY</div><h2>Na co si tipneš?</h2></div></div><div class="content-grid">${upcoming.filter(e=>e.type==='scrim'||e.type==='tournament').slice(0,4).map(e=>{const picked=JSON.parse(localStorage.getItem('gg_picks')||'{}')[e.id];return `<section class="panel"><div class="panel-head"><div><h3>${esc(e.title)}</h3><p>${fmtDate(e.date,{weekday:'long',day:'numeric',month:'long'})} · ${new Date(e.date).toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit'})}</p></div>${eventType(e.type)}</div><div class="pick-row"><button class="pick-button ${picked==='win'?'selected':''}" data-pick="win" data-match="${esc(e.id)}"><b>⚡ Výhra</b>+ 15 bodů</button><button class="pick-button ${picked==='lose'?'selected':''}" data-pick="lose" data-match="${esc(e.id)}"><b>◉ Těsný zápas</b>+ 5 bodů</button></div><p style="padding:0 13px 12px;color:#69788c;font-size:8px">Vyhodnocení mohou provést administrátoři po zápase.</p></section>`}).join('')||'<div class="empty panel" style="grid-column:1/-1"><b>Zatím nejsou naplánované zápasy</b>Až se v kalendáři objeví scrim nebo turnaj, budete si moct tipnout.</div>'}</div><div class="notice warn" style="margin-top:14px">🎮 Body jsou čistě zábavný prvek pro týmovou motivaci. Nejde o peníze ani skutečné sázení.</div>`}
function renderAdmin(){const allowed=['events','attendance','roster','playbook','sync','users','storage'].filter(k=>hasPermission(k));if(!allowed.includes(state.adminTab))state.adminTab=allowed[0]||'events';const events=eventsSorted(),tab=state.adminTab;return `${pageHeading('KONTROLA TÝMU','Administrace','Správa kalendáře, docházky a synchronizace.') }<div class="admin-tabs">${[['events','Kalendář','events'],['attendance','Docházka','attendance'],['roster','Soupiska','roster'],['playbook','Playbook','playbook'],['sync','Služba','sync'],['users','Účty / admini','users'],['storage','Data & zálohy','storage']].filter(([, ,p])=>hasPermission(p)).map(([v,label])=>`<button class="tab-button ${tab===v?'active':''}" data-admin-tab="${v}">${label}</button>`).join('')}</div>${tab==='events'?`<div class="admin-grid"><section class="panel"><div class="panel-head"><div><h3>Nová událost</h3><p>Vytvořte trénink, zápas nebo turnaj.</p></div></div><div style="padding:15px"><form id="eventForm"><div class="form-grid"><div class="field full"><label>NÁZEV AKCE</label><input required name="title" maxlength="90" placeholder="Např. Main roster · Inferno training"></div><div class="field"><label>DATUM A ČAS</label><input required type="datetime-local" name="date"></div><div class="field"><label>TYP AKCE</label><select name="type"><option value="training">Trénink</option><option value="scrim">Scrim / zápas</option><option value="tournament">Turnaj</option><option value="meeting">Meeting</option></select></div><div class="field"><label>POVINNÁ ÚČAST</label><select name="mandatory"><option value="yes">Ano, povinná</option><option value="no">Ne, dobrovolná</option></select></div><div class="field"><label>MAPA / MÍSTO</label><input name="location" maxlength="60" placeholder="Inferno · FACEIT"></div><div class="field full"><label>POZNÁMKY PRO TÝM</label><textarea name="description" maxlength="700" placeholder="Plán, příprava a další informace…"></textarea></div></div><div class="form-actions"><button class="btn btn-primary" type="submit">＋ Vytvořit událost</button></div></form></div></section><section class="panel"><div class="panel-head"><div><h3>V kalendáři</h3><p>${events.length} akcí celkem</p></div></div><div class="date-list">${events.slice().reverse().slice(0,8).map(e=>`${eventRow(e)}<div style="text-align:right;margin-top:-7px;margin-bottom:7px"><button class="btn btn-small btn-danger" data-delete-event="${esc(e.id)}">Odstranit</button></div>`).join('')||'<div class="empty">Kalendář je prázdný.</div>'}</div></section></div>`:tab==='roster'?renderRosterAdmin():tab==='playbook'?`<section class="panel"><div class="panel-head"><div><h3>Playbook</h3><p>Otevři Playbook a spravuj taktiky.</p></div><a class="btn btn-primary" href="#playbook">Otevřít →</a></div></section>`:tab==='attendance'?`<section class="panel"><div class="panel-head"><div><h3>Správa docházky</h3><p>Označte stav člena po uskutečněné události.</p></div></div><div style="padding:15px"><div class="field" style="max-width:460px"><label>VYBRAT UDÁLOST</label><select id="attendanceEvent">${events.map(e=>`<option value="${esc(e.id)}">${esc(e.title)} · ${fmtDate(e.date,{day:'numeric',month:'short'})}</option>`).join('')}</select></div><div id="attendanceRows" style="margin-top:12px"></div></div></section>`:tab==='users'?renderAccountTab():tab==='sync'?renderSyncTab():renderStorageTab()}`}
function renderSyncTab(){return '<section class=\"panel\"><div class=\"panel-head\"><h3>Stav týmového hubu</h3><p>Zabezpečená služba Freezers ESPORT.</p></div></section>'}
function renderStorageTab(){return '<section class=\"panel\"><h3>Zálohy Freezers ESPORT</h3><button class=\"btn btn-primary\" data-action=\"export-data\">Stáhnout šifrovanou zálohu</button></section>'}
function renderAccountTab(){const owner=state.userRole==='owner';return `${pageHeading('PŘÍSTUPY','Účty a administrátoři','Účet FILAS má roli owner. Owner může zakládat další účty a udělovat roli admina.') }<div class="admin-grid"><section class="panel"><div class="panel-head"><div><h3>Týmové účty</h3><p>${state.admins.length} přihlašovacích účtů</p></div></div>${state.admins.map(a=>`<div class="record-line"><span>${esc(a.username)} ${a.username.toLowerCase()==='filas'?'<small style="color:#ffc46b">· OWNER</small>':''}</span><span><span class="event-type">${esc(String(a.role||'member').toUpperCase())}</span>${owner&&a.role!=='owner'?` <button class="btn btn-small btn-danger" data-remove-account="${esc(a.username)}">Odebrat</button>`:''}</span></div>`).join('')}</section><section class="panel"><div class="panel-head"><div><h3>Přidat účet</h3><p>Heslo se uloží jako odvozený hash, ne jako text.</p></div></div>${owner?`<div style="padding:15px"><form id="accountForm"><div class="form-grid"><div class="field full"><label>USERNAME</label><input name="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_.-]+" autocomplete="off"></div><div class="field full"><label>HESLO (MIN. 10 ZNAKŮ)</label><input name="password" type="password" required minlength="10" autocomplete="new-password"></div><div class="field full"><label>ROLE</label><select name="role"><option value="member">Člen</option><option value="admin">Admin</option></select></div></div><div class="form-actions"><button class="btn btn-primary">Vytvořit účet</button></div></form></div>`:'<div class="empty">Nové účty a další adminy může přidávat jen owner FILAS.</div>'}</section></div><section class="panel" style="margin-top:13px"><div class="panel-head"><div><h3>Změnit své heslo</h3><p>Po prvním přihlášení nahraď výchozí heslo silným heslem.</p></div></div><div style="padding:15px"><form id="changePasswordForm"><div class="form-grid"><div class="field"><label>SOUČASNÉ HESLO</label><input type="password" name="currentPassword" required autocomplete="current-password"></div><div class="field"><label>NOVÉ HESLO (MIN. 10 ZNAKŮ)</label><input type="password" name="newPassword" required minlength="10" autocomplete="new-password"></div></div><div class="form-actions"><button class="btn btn-primary">Uložit nové heslo</button></div></form></div></section><div class="notice warn" style="margin-top:13px">Oprávnění se ověřují při každém zápisu v zabezpečené službě.</div>`}
function validImportedData(k,v){if(['events','admins','staff'].includes(k))return Array.isArray(v);if(k==='roster')return v&&typeof v==='object'&&!Array.isArray(v);if(k==='playbook')return v&&typeof v==='object'&&Array.isArray(v.entries);return v&&typeof v==='object'&&!Array.isArray(v)}
function exportBackup(){const data={};for(const k of Object.keys(DATA_FILES))data[k]=state[k];const payload={app:'Freezers ESPORT Team Hub',version:1,exportedAt:new Date().toISOString(),data};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`freezers-esport-zaloha-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast('JSON záloha byla stažena.')}
function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),payload=parsed.data||parsed,valid=Object.keys(DATA_FILES).filter(k=>Object.hasOwn(payload,k)&&validImportedData(k,payload[k]));if(!valid.length)throw Error('V souboru nebyla nalezena platná týmová data.');if(!confirm(`Načíst ${valid.length} datových souborů? Aktuální místní kopie se nahradí.`))return;valid.forEach(k=>state[k]=payload[k]);saveLocal();render();toast(`Načteno ${valid.length} souborů ze zálohy.`)}catch(err){toast(`Zálohu nelze načíst: ${err.message}`,'error')}};reader.readAsText(file)}
function isAdmin(){return state.userRole==='owner'||state.userRole==='admin'}
function hexBytes(hex){return Uint8Array.from(hex.match(/.{1,2}/g)||[],b=>parseInt(b,16))}
function toHex(bytes){return [...new Uint8Array(bytes)].map(v=>v.toString(16).padStart(2,'0')).join('')}
async function passwordDigest(password,salt,iterations=600000){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:hexBytes(salt),iterations,hash:'SHA-256'},material,256);return toHex(bits)}
async function login(form){const d=new FormData(form),username=String(d.get('username')||'').trim(),password=String(d.get('password')||'');try{const auth=await apiRequest('/api/login',{method:'POST',body:JSON.stringify({username,password})});state.apiSession=auth.session;state.username=auth.user.username;state.userRole=auth.user.role;state.permissions=auth.user.permissions||{};state.currentUser=auth.user.username;state.authenticated=true;await syncAll();setCookie('freezers_user',state.username);render();toast('Přihlášení proběhlo. Vítej ve Freezers ESPORT.')}catch(err){state.apiSession='';state.authenticated=false;state.github=false;state.currentUser=null;state.userRole=null;state.permissions={};toast('Přihlášení se nezdařilo: '+err.message,'error')}}
function logout(){state.authenticated=false;state.github=false;state.apiSession='';state.currentUser=null;state.userRole=null;state.permissions={};state.username='FILAS';$('#loginPassword').value='';render();openLogin()}
async function createAccount(form){if(state.userRole!=='owner'){toast('Nové účty může vytvářet jen owner.','error');return}const data=new FormData(form),username=String(data.get('username')||'').trim(),password=String(data.get('password')||''),role=data.get('role')==='admin'?'admin':'member',permissions=Object.fromEntries(data.getAll('permissions').map(k=>[String(k),true]));if(state.admins.some(a=>a.username.toLowerCase()===username.toLowerCase())){toast('Toto uživatelské jméno už existuje.','error');return}if(password.length<10){toast('Heslo musí mít alespoň 10 znaků.','error');return}const salt=toHex(crypto.getRandomValues(new Uint8Array(16)));try{const passwordHash=await passwordDigest(password,salt);state.admins.push({username,role,...(role==='admin'?{permissions}:{}),salt,passwordHash,iterations:600000,createdAt:new Date().toISOString()});saveLocal();log(`${state.username} vytvořil účet ${username} (${role}).`,'♟');persist('admins');render();toast(`Účet ${username} byl vytvořen.`)}catch(err){toast(`Účet se nepodařilo vytvořit: ${err.message}`,'error')}}
async function changePassword(form){const data=new FormData(form),oldPassword=String(data.get('currentPassword')||''),newPassword=String(data.get('newPassword')||''),account=state.admins.find(a=>a.username.toLowerCase()===state.username.toLowerCase());if(!account||await passwordDigest(oldPassword,account.salt,account.iterations||600000)!==account.passwordHash){toast('Současné heslo není správné.','error');return}if(newPassword.length<10){toast('Nové heslo musí mít alespoň 10 znaků.','error');return}const salt=toHex(crypto.getRandomValues(new Uint8Array(16)));account.salt=salt;account.passwordHash=await passwordDigest(newPassword,salt);account.iterations=600000;saveLocal();log(`${state.username} změnil své heslo.`,'⚿');persist('admins');form.reset();toast('Heslo bylo změněno.')}
function openLogin(){if(state.authenticated){location.hash='member';return}$('#loginScreen').hidden=false;$('#loginUsername').focus()}
$('#loginClose').addEventListener('click',()=>$('#loginScreen').hidden=true);
function restrictedPrompt(area){return `${pageHeading('ČLENSKÁ SEKCE',area==='kalendář'?'Kalendář týmu':'Týmový playbook','Tato část je dostupná přihlášeným členům.',`<button class="btn btn-primary" data-action="open-login">Přihlásit se →</button>`)}<section class="panel"><div class="empty"><b>Nejdřív se přihlas do Freezers ESPORT</b>Přihlas se svým týmovým jménem a heslem.</div></section>`}
function renderMember(){if(!state.authenticated)return restrictedPrompt('členskou sekci');const ev=futureEvents().slice(0,5),mine=e=>Object.entries(state.rsvps[e.id]||{}).find(([u])=>u.toLowerCase()===state.username.toLowerCase())?.[1],yes=ev.filter(e=>mine(e)==='yes').length;return `${pageHeading('PLAYER HUB','Členská sekce',`Vítej zpět, ${esc(state.username)}. Tady máš týmový rozvrh a přístup k přípravě.`,`<button class="btn" data-action="logout">Odhlásit se</button>`)}<div class="stats-grid"><div class="stat-card"><div class="stat-label">PŘIHLÁŠENÝ ÚČET</div><div class="stat-value blue" style="font-size:25px">${esc(state.username)}</div><div class="stat-note">role ${esc(state.userRole||'member')}</div></div><div class="stat-card"><div class="stat-label">NADCHÁZEJÍCÍ AKCE</div><div class="stat-value">${ev.length}</div><div class="stat-note">v týmovém kalendáři</div></div><div class="stat-card"><div class="stat-label">POTVRZENÁ ÚČAST</div><div class="stat-value green">${yes}</div><div class="stat-note">zobrazených akcí</div></div><div class="stat-card"><div class="stat-label">ČLENSKÉ MATERIÁLY</div><div class="stat-value">${state.playbook.entries?.length||0}</div><div class="stat-note">taktik v playbooku</div></div></div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h3>Kalendář týmu</h3><p>Potvrď účast nebo pošli omluvenku.</p></div><a class="text-link" href="#calendar">OTEVŘÍT →</a></div><div class="event-list">${ev.length?ev.slice(0,4).map(eventRow).join(''):'<div class="empty">Zatím nejsou naplánované akce.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h3>Členský playbook</h3><p>Callouty a týmové setupy.</p></div><a class="text-link" href="#playbook">OTEVŘÍT →</a></div><div class="empty"><b>${state.playbook.entries?.length||0} taktik připravených</b>Otevři playbook a prohlédni si setupy podle map.</div></section></div>`}
init();

const PERMISSIONS={roster:'Soupiska',events:'Kalendář a události',attendance:'Docházka',playbook:'Playbook',sync:'GitHub synchronizace',users:'Účty a admini',storage:'Zálohy a lokální data'};
function hasPermission(key){if(state.userRole==='owner')return true;if(state.userRole!=='admin')return false;const a=state.admins.find(x=>x.username?.toLowerCase()===String(state.username).toLowerCase());return a?.permissions?a.permissions[key]===true:true}
function isAdmin(){return state.userRole==='owner'||(state.userRole==='admin'&&Object.keys(PERMISSIONS).some(hasPermission))}
function permissionFields(selected={}){return Object.entries(PERMISSIONS).map(([k,label])=>'<label class="permission-option"><input type="checkbox" name="permissions" value="'+k+'" '+(selected[k]?'checked':'')+'><span>'+label+'</span></label>').join('')}
function renderRosterGroup(group,items,absences){const labels={main:['MAIN ROSTER','HLAVNÍ SESTAVA'],reserve:['RESERVE MAIN','REZERVA'],academy:['ACADEMY','AKADEMIE'],'academy-reserve':['ACADEMY · RESERVE','REZERVA AKADEMIE']},[kicker,title]=labels[group]||[group.toUpperCase(),group];return '<section class="panel"><div class="panel-head"><div><span class="section-kicker">'+kicker+'</span><h3 class="group-head">'+title+'<span>'+items.filter(p=>p?.name&&p.type!=='empty').length+' HRÁČŮ</span></h3></div>'+(hasPermission('roster')?'<button class="btn btn-small btn-primary" data-add-player="'+esc(group)+'">＋ Přidat hráče</button>':'')+'</div><div class="players-grid">'+items.map((p,index)=>{if(!p||p.type==='empty')return '<a class="vacancy-card" href="https://discord.gg/Ntcz76sXkP" target="_blank" rel="noopener"><span class="vacancy-plus">＋</span><span><b>Volné místo</b><small>Přidej se k týmu na Discordu ↗</small></span></a>';const n=absences[p.name]||0;return '<div class="player-card '+(n>=5?'alert':'')+'"><span class="player-avatar">'+esc(initials(p.name))+'</span><span class="player-info"><b>'+esc(p.name)+'</b><small>'+esc(p.role||'Člen týmu')+'</small></span>'+(p.faceit?'<a class="text-link" href="'+esc(p.faceit)+'" target="_blank" rel="noopener">FACEIT ↗</a>':'')+(p.steam?'<a class="text-link" href="'+esc(p.steam)+'" target="_blank" rel="noopener">STEAM ↗</a>':'')+(n>=5?'<span class="absence-pill">⚠ '+n+'×</span>':'')+(hasPermission('roster')?'<span class="player-admin-actions"><button class="btn btn-small" data-edit-player="'+esc(group)+'" data-player-index="'+index+'">Upravit</button><button class="btn btn-small btn-danger" data-delete-player="'+esc(group)+'" data-player-index="'+index+'">×</button></span>':'')+'</div>'}).join('')+'</div></section>'}
function renderRoster(){const {absences}=counts();return pageHeading('SESTAVY FREEZERS','Roster','Přehled sestav Freezers ESPORT.')+'<div class="roster-groups">'+Object.entries(state.roster||{}).map(([g,items])=>renderRosterGroup(g,items||[],absences)).join('')+'</div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><span class="section-kicker">PŘIDEJ SE K FREEZERS</span><h3 class="group-head">Hledáme nové tváře</h3><p>Napiš nám na Discordu.</p></div><a class="btn btn-primary" href="https://discord.gg/Ntcz76sXkP" target="_blank" rel="noopener">Připojit se na Discord ↗</a></div></section>'}
function playerModal(group,index){if(!hasPermission('roster'))return toast('Nemáš oprávnění spravovat soupisku.','error');const edit=Number.isInteger(index),p=edit?(state.roster[group]||[])[index]||{}:{};modal('<span class="eyebrow">SPRÁVA SOUPISKY</span><h2>'+(edit?'Upravit hráče':'Přidat hráče')+'</h2><form id="playerForm"><input type="hidden" name="sourceGroup" value="'+esc(group)+'"><input type="hidden" name="sourceIndex" value="'+(edit?index:'')+'"><div class="form-grid"><div class="field full"><label>JMÉNO HRÁČE</label><input name="name" required maxlength="48" value="'+esc(p.name||'')+'"></div><div class="field"><label>SESTAVA</label><select name="group">'+Object.keys(state.roster||{}).map(g=>'<option value="'+esc(g)+'" '+(g===group?'selected':'')+'>'+esc(g)+'</option>').join('')+'</select></div><div class="field"><label>STATUS</label><select name="type"><option value="player">Hráč</option><option value="captain" '+(p.type==='captain'?'selected':'')+'>Kapitán</option><option value="trial" '+(p.type==='trial'?'selected':'')+'>Na zkoušku</option></select></div><div class="field full"><label>ROLE / POPIS</label><input name="role" maxlength="80" value="'+esc(p.role||'')+'"></div><div class="field full"><label>FACEIT PROFIL</label><input name="faceit" type="url" value="'+esc(p.faceit||'')+'" placeholder="https://www.faceit.com/…"></div><div class="field full"><label>STEAM PROFIL</label><input name="steam" type="url" value="'+esc(p.steam||'')+'" placeholder="https://steamcommunity.com/…"></div></div><div class="form-actions"><button class="btn btn-primary">'+(edit?'Uložit změny':'Přidat hráče')+'</button></div></form>')}
function savePlayer(form){if(!hasPermission('roster'))return toast('Nemáš oprávnění spravovat soupisku.','error');const d=new FormData(form),from=String(d.get('sourceGroup')),idx=d.get('sourceIndex')===''?null:Number(d.get('sourceIndex')),to=String(d.get('group')),p={name:String(d.get('name')||'').trim(),role:String(d.get('role')||'').trim(),type:String(d.get('type')||'player'),faceit:String(d.get('faceit')||'').trim(),steam:String(d.get('steam')||'').trim()};if(!p.name||!state.roster[to])return toast('Zkontroluj jméno a sestavu.','error');if(idx!==null){const old=state.roster[from]?.[idx];if(!old)return toast('Hráče se nepodařilo najít.','error');if(old.name!==p.name)for(const values of Object.values(state.attendance||{}))if(values[old.name]!==undefined){values[p.name]=values[old.name];delete values[old.name]}state.roster[from].splice(idx,1)}if(!Array.isArray(state.roster[to]))state.roster[to]=[];if(idx===null||to!==from)state.roster[to].push(p);else state.roster[to].splice(Math.min(idx,state.roster[to].length),0,p);saveLocal();log(state.username+' uložil hráče '+p.name+'.','♟');persist('roster');persist('attendance');$('#modal').close();render();toast('Soupiska uložena.')}
function deletePlayer(group,index){if(!hasPermission('roster'))return toast('Nemáš oprávnění spravovat soupisku.','error');const p=state.roster[group]?.[index];if(!p||p.type==='empty'||!confirm('Odebrat hráče '+p.name+' ze soupisky?'))return;state.roster[group].splice(index,1);saveLocal();log(state.username+' odebral hráče '+p.name+'.','×');persist('roster');render()}
function renderRosterAdmin(){return '<section class="panel"><div class="panel-head"><div><h3>Správa hráčů</h3><p>Přidej hráče, uprav jméno a profily nebo ho přesuň do jiné sestavy.</p></div></div>'+Object.entries(state.roster||{}).map(([g,items])=>'<div class="record-line"><span>'+esc(g)+' · '+(items||[]).filter(p=>p?.name&&p.type!=='empty').length+' hráčů</span><button class="btn btn-small btn-primary" data-add-player="'+esc(g)+'">＋ Přidat hráče</button></div>').join('')+'</section>'}
function renderAccountTab(){const owner=state.userRole==='owner';return pageHeading('PŘÍSTUPY','Účty a administrátoři','Owner může přiřazovat oprávnění adminům.')+'<div class="admin-grid"><section class="panel"><div class="panel-head"><div><h3>Týmové účty</h3><p>'+state.admins.length+' účtů</p></div></div>'+state.admins.map(a=>'<div class="record-line"><span>'+esc(a.username)+' · '+esc(a.role||'member')+'</span><span>'+(owner&&a.role!=='owner'?'<button class="btn btn-small" data-edit-perms="'+esc(a.username)+'">Oprávnění</button> <button class="btn btn-small btn-danger" data-remove-account="'+esc(a.username)+'">Odebrat</button>':'')+'</span></div>').join('')+'</section><section class="panel"><div class="panel-head"><div><h3>Přidat účet</h3><p>Admin dostane jen vybraná oprávnění.</p></div></div>'+(owner?'<div style="padding:15px"><form id="accountForm"><div class="form-grid"><div class="field full"><label>USERNAME</label><input name="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_.-]+"></div><div class="field full"><label>HESLO (MIN. 10 ZNAKŮ)</label><input name="password" type="password" required minlength="10"></div><div class="field full"><label>ROLE</label><select name="role"><option value="member">Člen</option><option value="admin">Admin</option></select></div><div class="field full"><label>OPRÁVNĚNÍ ADMINA</label><div class="permission-grid">'+permissionFields({roster:true,events:true,attendance:true,playbook:true})+'</div></div></div><div class="form-actions"><button class="btn btn-primary">Vytvořit účet</button></div></form></div>':'<div class="empty">Účty může spravovat pouze owner.</div>')+'</section></div><section class="panel" style="margin-top:13px"><div class="panel-head"><div><h3>Změnit své heslo</h3><p>Nastav si bezpečné heslo.</p></div></div><div style="padding:15px"><form id="changePasswordForm"><div class="form-grid"><div class="field"><label>SOUČASNÉ HESLO</label><input type="password" name="currentPassword" required></div><div class="field"><label>NOVÉ HESLO (MIN. 10 ZNAKŮ)</label><input type="password" name="newPassword" required minlength="10"></div></div><div class="form-actions"><button class="btn btn-primary">Uložit nové heslo</button></div></form></div></section>'}

document.addEventListener('click',e=>{const x=e.target.closest('[data-edit-player]');if(x)return playerModal(x.dataset.editPlayer,Number(x.dataset.playerIndex));const a=e.target.closest('[data-add-player]');if(a)return playerModal(a.dataset.addPlayer);const d=e.target.closest('[data-delete-player]');if(d)return deletePlayer(d.dataset.deletePlayer,Number(d.dataset.playerIndex));const b=e.target.closest('[data-edit-perms]');if(b&&state.userRole==='owner'){const u=state.admins.find(x=>x.username===b.dataset.editPerms);if(u){const chosen=u.permissions||Object.fromEntries(Object.keys(PERMISSIONS).map(k=>[k,true]));modal('<span class="eyebrow">PŘÍSTUPY</span><h2>Oprávnění: '+esc(u.username)+'</h2><form id="permissionsForm"><input type="hidden" name="username" value="'+esc(u.username)+'"><div class="permission-grid">'+permissionFields(chosen)+'</div><div class="form-actions"><button class="btn btn-primary">Uložit oprávnění</button></div></form>')}}});
document.addEventListener('submit',e=>{if(e.target.id==='playerForm'){e.preventDefault();savePlayer(e.target)}if(e.target.id==='permissionsForm'){e.preventDefault();if(state.userRole!=='owner')return;const d=new FormData(e.target),a=state.admins.find(x=>x.username===d.get('username'));if(!a)return;a.permissions=Object.fromEntries(d.getAll('permissions').map(k=>[String(k),true]));saveLocal();persist('admins');$('#modal').close();render();toast('Oprávnění uložena.')}});

async function apiRequest(path,options={}){if(!API_BASE)throw Error('Týmová služba ještě není nakonfigurovaná.');const headers={'Content-Type':'application/json',...(state.apiSession?{Authorization:'Bearer '+state.apiSession}:{})};const response=await fetch(API_BASE+path,{...options,headers:{...headers,...options.headers}});const body=await response.json().catch(()=>({}));if(!response.ok)throw Error(body.error||('HTTP '+response.status));return body}
async function githubRead(kind){return apiRequest('/api/data/'+encodeURIComponent(kind))}
async function githubWrite(kind){if(!state.apiSession)return;return apiRequest('/api/data/'+encodeURIComponent(kind),{method:'PUT',body:JSON.stringify({data:state[kind]})})}
async function syncAll(){if(!state.apiSession)throw Error('Přihlas se do týmového hubu.');const payload=await apiRequest('/api/data');for(const [k,v] of Object.entries(payload))if(Object.hasOwn(state,k))state[k]=v;state.github=true;render()}
async function login(form){const d=new FormData(form),username=String(d.get('username')||'').trim(),password=String(d.get('password')||'');try{const auth=await apiRequest('/api/login',{method:'POST',body:JSON.stringify({username,password})});state.apiSession=auth.session;state.username=auth.user.username;state.userRole=auth.user.role;state.permissions=auth.user.permissions||{};state.currentUser=auth.user.username;state.authenticated=true;await syncAll();setCookie('freezers_user',state.username);render();toast('Přihlášení proběhlo. Vítej ve Freezers ESPORT.')}catch(err){state.apiSession='';state.authenticated=false;state.github=false;state.currentUser=null;state.userRole=null;state.permissions={};toast('Přihlášení se nezdařilo: '+err.message,'error')}}
function logout(){state.authenticated=false;state.github=false;state.apiSession='';state.currentUser=null;state.userRole=null;state.permissions={};state.username='FILAS';$('#loginPassword').value='';render();openLogin()}
function saveLocal(){if(API_BASE&&state.apiSession)return;const o={};for(const k of Object.keys(DATA_FILES))if(k!=='admins')o[k]=state[k];localStorage.setItem(key,JSON.stringify(o))}
async function init(){if(!['month','week','day'].includes(state.calendarView))state.calendarView='month';if(!getCookie('freezers_user'))setCookie('freezers_user',state.username);if(API_BASE){try{const d=await apiRequest('/api/public');state.events=d.events||[];state.roster=d.roster||DEFAULTS.roster;state.playbook=d.playbook||DEFAULTS.playbook;state.publicPlaybookCount=d.playbookCount||0;state.github=true}catch(err){state.github=false;toast('Freezers ESPORT se načte po aktivaci týmové služby.','error')}}else{const files=Object.keys(DATA_FILES).filter(k=>k!=='admins');const values=await Promise.all(files.map(async k=>{try{const r=await fetch(DATA_FILES[k]);return r.ok?await r.json():structuredClone(DEFAULTS[k])}catch{return structuredClone(DEFAULTS[k])}}));files.forEach((k,i)=>state[k]=values[i])}render()}
function renderSyncTab(){return '<section class="panel"><div class="panel-head"><div><h3>Stav týmového hubu</h3><p>Freezers ESPORT se synchronizuje zabezpečeným připojením.</p></div></div><div class="github-status"><div class="status-indicator '+(state.github?'connected':'')+'"><span class="sync-light"></span>'+(state.github?'ZABEZPEČENÉ PŘIPOJENÍ AKTIVNÍ':'ČEKÁ NA AKTIVACI SLUŽBY')+'</div><p>'+(state.github?'Přístup i data jsou chráněné a spravované službou.':'Služba musí být nasazená ownerem.')+'</p>'+(state.userRole==='owner'&&state.github?'<button class="btn btn-primary" data-action="encrypt-data">Zašifrovat týmové JSON soubory</button>':'')+'</div></section>'}
function hasPermission(key){if(state.userRole==='owner')return true;if(state.userRole!=='admin')return false;return state.permissions?state.permissions[key]===true:true}

document.addEventListener('click',e=>{if(e.target.closest('.modal-close')){$('#modal').close();return}const remove=e.target.closest('[data-remove-account]');if(remove){if(state.userRole!=='owner')return toast('Účty může spravovat jen owner.','error');if(confirm('Odebrat účet '+remove.dataset.removeAccount+'?')){state.admins=state.admins.filter(a=>a.username.toLowerCase()!==remove.dataset.removeAccount.toLowerCase());saveLocal();persist('admins');render()}return}const del=e.target.closest('[data-delete-event]');if(del){if(!hasPermission('events'))return toast('Nemáš oprávnění spravovat události.','error');if(confirm('Opravdu odstranit tuto událost?')){state.events=state.events.filter(x=>x.id!==del.dataset.deleteEvent);saveLocal();persist('events');render()}return}const nav=e.target.closest('a[data-page]');if(nav){$('#sidebar').classList.remove('open');return}const ev=e.target.closest('[data-event]');if(ev&&!e.target.closest('[data-rsvp]')&&!e.target.closest('[data-action]')){eventModal(ev.dataset.event);return}const a=e.target.closest('[data-action]')?.dataset.action;if(a==='open-login')return openLogin();if(a==='logout')return logout();if(a==='add-event')return hasPermission('events')?addEventModal():toast('Nemáš oprávnění přidávat události.','error');if(a==='cal-prev'){state.calendarDate.setMonth(state.calendarDate.getMonth()-1);render()}if(a==='cal-next'){state.calendarDate.setMonth(state.calendarDate.getMonth()+1);render()}if(a==='cal-today'){state.calendarDate=new Date();render()}if(a==='encrypt-data'&&state.userRole==='owner')apiRequest('/api/migrate',{method:'POST',body:'{}'}).then(()=>toast('Týmová JSON data jsou zašifrovaná.')).catch(err=>toast(err.message,'error'));if(a==='sync-now'&&hasPermission('sync'))syncAll().catch(err=>toast(err.message,'error'));if(a==='export-data'&&hasPermission('storage'))exportBackup();if(a==='edit-name'){const name=prompt('Jaké jméno se má zobrazovat?',state.username);if(name?.trim()){state.username=name.trim().slice(0,32);setCookie('freezers_user',state.username);render()}}if(a==='reset-local'&&hasPermission('storage')&&confirm('Odstranit místní změny a znovu načíst původní data?')){localStorage.removeItem(key);localStorage.removeItem('gg_overrides_v1');location.reload()}if(a==='excuse')excuse(e.target.closest('[data-event]').dataset.event);if(a==='add-strat'&&hasPermission('playbook'))modal('<span class="eyebrow">CS2 TACTICAL BOARD</span><h2>Přidat taktiku</h2><form id="stratForm"><div class="form-grid"><div class="field full"><label>NÁZEV SETUPU</label><input required name="title" maxlength="90"></div><div class="field"><label>MAPA</label><select name="map">'+(state.playbook.maps||[]).map(m=>'<option>'+esc(m.name)+'</option>').join('')+'</select></div><div class="field"><label>YOUTUBE EMBED / ODKAZ</label><input name="videoLink" type="url"></div><div class="field full"><label>POKYN / POPISEK</label><textarea name="description"></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Uložit taktiku</button></div></form>');const map=e.target.closest('[data-map]');if(map){state.map=map.dataset.map;render()}const view=e.target.closest('[data-view]');if(view){state.calendarView=view.dataset.view;setCookie('freezers_calendar_view',state.calendarView);render()}const tab=e.target.closest('[data-admin-tab]');if(tab){if(!hasPermission(tab.dataset.adminTab))return toast('Tato část administrace není povolená.','error');state.adminTab=tab.dataset.adminTab;render()}const pick=e.target.closest('[data-pick]');if(pick)pickMatch(pick.dataset.match,pick.dataset.pick);const response=e.target.closest('[data-rsvp]');if(response)rsvp(response.dataset.event,response.dataset.rsvp);if(e.target.id==='logToggle')$('#activityPanel').classList.toggle('open');if(e.target.id==='closeLogs')$('#activityPanel').classList.remove('open');if(e.target.id==='mobileMenu')$('#sidebar').classList.toggle('open');if(e.target.closest('#profileButton,#topProfile'))state.authenticated?logout():openLogin()});
document.addEventListener('submit',e=>{if(e.target.id==='loginForm'){e.preventDefault();login(e.target)}if(e.target.id==='accountForm'){e.preventDefault();createAccount(e.target)}if(e.target.id==='changePasswordForm'){e.preventDefault();changePassword(e.target)}if(e.target.id==='eventForm'||e.target.id==='quickEventForm'){e.preventDefault();createEvent(e.target)}if(e.target.id==='stratForm'){e.preventDefault();if(!hasPermission('playbook'))return toast('Nemáš oprávnění.','error');const d=new FormData(e.target);state.playbook.entries.push({title:String(d.get('title')||'').trim(),map:d.get('map'),videoLink:d.get('videoLink'),description:d.get('description'),addedAt:new Date().toISOString()});saveLocal();persist('playbook');$('#modal').close();render();toast('Taktika uložena.')}});
document.addEventListener('change',e=>{if(e.target.id==='importFile'&&e.target.files?.[0]){if(!hasPermission('storage'))return toast('Nemáš oprávnění obnovit zálohu.','error');importBackup(e.target.files[0])}if(e.target.id==='attendanceEvent')renderAttendanceEditor();if(e.target.matches('[data-attendee]'))setAttendance($('#attendanceEvent').value,e.target.dataset.attendee,e.target.value)});
document.addEventListener('input',e=>{if(e.target.id==='stratSearch'){state.search=e.target.value;const pos=e.target.selectionStart;render();const input=$('#stratSearch');input?.focus();input?.setSelectionRange(pos,pos)}});window.addEventListener('hashchange',render);

function modal(content){$('#modalBody').innerHTML=content;$('#modal').showModal()}
function persist(kind){saveLocal();if(state.github&&state.apiSession)githubWrite(kind).catch(err=>toast('Uložení se nezdařilo: '+err.message,'error'))}
function renderLogs(){const box=$('#activityList');if(!box)return;box.innerHTML=(state.logs||[]).slice(0,35).map(x=>'<div class="activity-item"><span class="activity-icon">'+esc(x.icon||'↗')+'</span><div><p>'+esc(x.message||'')+'</p><time>'+esc(x.at?fmtDate(x.at,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'')+'</time></div></div>').join('')||'<div class="empty">Zatím tu nejsou žádné události.</div>'}
function render(){if(state.authenticated)$('#loginScreen').hidden=true;const route=location.hash.slice(1)||state.page;state.page=['dashboard','calendar','playbook','roster','hazard','member','admin'].includes(route)?route:'dashboard';if(state.page==='admin'&&!isAdmin()){state.page='dashboard';location.hash='dashboard'}if(state.adminTab==='storage'&&!hasPermission('storage'))state.adminTab='events';document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===state.page);if(a.dataset.page==='admin')a.hidden=!isAdmin()});$('#breadcrumb').textContent=({dashboard:'PŘEHLED',calendar:'KALENDÁŘ',playbook:'PLAYBOOK',roster:'SOUPISKA',hazard:'TIPOVAČKA',member:'ČLENSKÁ SEKCE',admin:'ADMINISTRACE'})[state.page];$('#sideUsername').textContent=state.authenticated?state.username:'Přihlásit se';$('#topUsername').textContent=state.authenticated?state.username:'Přihlásit se';$('#sideRole').textContent=state.authenticated?String(state.userRole||'member').toUpperCase():'Členský přístup';$('#page').innerHTML=({dashboard:renderDashboard,calendar:renderCalendar,playbook:renderPlaybook,roster:renderRoster,hazard:renderHazard,member:renderMember,admin:renderAdmin})[state.page]();$('#upcomingCount').textContent=futureEvents().length||'';renderLogs();$('#syncLabel').textContent=state.github?'Freezers připojen':'Lokální náhled';$('#syncHint').textContent=state.github?'Zabezpečený týmový hub':'Lokální náhled';if(state.adminTab==='attendance'&&state.page==='admin')renderAttendanceEditor()}
function storageBytes(){try{return new Blob([JSON.stringify(state)]).size}catch{return 0}}
function renderAttendanceEditor(){const sel=$('#attendanceEvent'),rows=$('#attendanceRows');if(!sel||!rows)return;const id=sel.value||state.events[0]?.id;if(!id){rows.innerHTML='<div class="empty">Nejprve vytvoř událost.</div>';return}rows.innerHTML=allPlayers().map(p=>{const status=state.attendance[id]?.[p.name]||'unmarked';return '<div class="record-line"><span>'+esc(p.name)+'</span><select data-attendee="'+esc(p.name)+'" style="background:#0a1019;color:#ccd6e4;border:1px solid #293547;border-radius:4px;padding:5px;font-size:9px"><option value="unmarked" '+(status==='unmarked'?'selected':'')+'>Neoznačeno</option><option value="present" '+(status==='present'?'selected':'')+'>Přítomen</option><option value="excused" '+(status==='excused'?'selected':'')+'>Omluven</option><option value="unexcused" '+(status==='unexcused'?'selected':'')+'>Neomluven</option></select></div>'}).join('')}
function setAttendance(id,user,status){if(!hasPermission('attendance'))return toast('Nemáš oprávnění měnit docházku.','error');state.attendance[id]??={};if(status==='unmarked')delete state.attendance[id][user];else state.attendance[id][user]=status;saveLocal();persist('attendance');log(state.username+' změnil docházku hráče '+user+'.','♟');render()}
function eventModal(id){const e=state.events.find(x=>x.id===id);if(!e)return;const rs=state.rsvps[id]||{},key=Object.keys(rs).find(x=>x.toLowerCase()===state.username.toLowerCase()),mine=key?rs[key]:'';modal('<span class="eyebrow">TÝMOVÝ KALENDÁŘ</span><h2>'+esc(e.title)+'</h2><div class="detail-meta">'+eventType(e.type)+'<span>▦ '+fmtDate(e.date,{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})+'</span><span>'+(e.mandatory==='yes'?'● Povinná účast':'○ Dobrovolná účast')+'</span></div>'+(e.location?'<p class="detail-description">⌖ '+esc(e.location)+'</p>':'')+'<p class="detail-description">'+esc(e.description||'Bez dalších poznámek.')+'</p><div class="notice" style="margin-top:15px">'+Object.keys(rs).length+' hráčů odpovědělo · '+Object.values(rs).filter(x=>x==='yes').length+' dorazí</div>'+(state.authenticated?'<div class="form-actions"><button class="btn '+(mine==='yes'?'btn-primary':'')+'" data-rsvp="yes" data-event="'+esc(id)+'">✓ Dorazím</button><button class="btn '+(mine==='no'?'btn-primary':'')+'" data-rsvp="no" data-event="'+esc(id)+'">✕ Nedostavím se</button><button class="btn" data-action="excuse" data-event="'+esc(id)+'">Poslat omluvenku</button></div>':'')+'</div>')}
function addEventModal(){if(!hasPermission('events'))return;modal('<span class="eyebrow">NOVÝ TÝMOVÝ BLOK</span><h2>Přidat událost</h2><form id="quickEventForm"><div class="form-grid"><div class="field full"><label>NÁZEV</label><input name="title" required maxlength="90"></div><div class="field"><label>DATUM A ČAS</label><input name="date" required type="datetime-local" value="'+new Date(Date.now()+86400000).toISOString().slice(0,16)+'"></div><div class="field"><label>TYP</label><select name="type"><option value="training">Trénink</option><option value="scrim">Scrim / zápas</option><option value="tournament">Turnaj</option><option value="meeting">Meeting</option></select></div><div class="field"><label>ÚČAST</label><select name="mandatory"><option value="yes">Povinná</option><option value="no">Dobrovolná</option></select></div><div class="field"><label>MAPA / MÍSTO</label><input name="location" maxlength="60"></div><div class="field full"><label>POPIS</label><textarea name="description" maxlength="700"></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Vytvořit</button></div></form>')}
function createEvent(form){if(!hasPermission('events'))return toast('Nemáš oprávnění přidávat události.','error');const d=new FormData(form),date=new Date(d.get('date')),title=String(d.get('title')||'').trim();if(!title||isNaN(date))return toast('Zkontroluj název a datum.','error');const ev={id:'ev_'+Date.now(),title,date:date.toISOString(),type:d.get('type'),description:String(d.get('description')||'').trim(),location:String(d.get('location')||'').trim(),mandatory:d.get('mandatory'),createdBy:state.username};state.events.push(ev);saveLocal();persist('events');log(state.username+' přidal událost „'+title+'“.','▦');$('#modal').close();render();toast('Událost byla přidána.')}
function rsvp(id,value){if(!state.authenticated)return openLogin();state.rsvps[id]??={};state.rsvps[id][state.username]=value;saveLocal();persist('rsvps');log(state.username+(value==='yes'?' potvrdil účast na ':' odmítl účast na ')+(state.events.find(x=>x.id===id)?.title||id)+'.','✓');$('#modal').close();render()}
function excuse(id){if(!state.authenticated)return openLogin();const reason=prompt('Důvod omluvenky (volitelné):','');if(reason===null)return;state.rsvps[id]??={};state.rsvps[id][state.username]='excused';state.attendance[id]??={};state.attendance[id][state.username]='excused';state.excuses[id]??={};state.excuses[id][state.username]={reason:reason.trim(),submittedAt:new Date().toISOString()};persist('rsvps');persist('attendance');persist('excuses');log(state.username+' poslal omluvenku.','✎');$('#modal').close();render();toast('Omluvenka zaznamenána.')}
function pickMatch(id,value){const picks=JSON.parse(localStorage.getItem('gg_picks')||'{}');picks[id]=value;localStorage.setItem('gg_picks',JSON.stringify(picks));state.points+=value==='win'?15:5;render();toast('Tip uložen.')}
function log(message,icon='↗'){state.logs.unshift({message,icon,at:new Date().toISOString()});state.logs=state.logs.slice(0,60);saveLocal();renderLogs();if(state.github&&state.userRole==='owner')persist('logs')}

async function changePassword(form){const d=new FormData(form);try{await apiRequest('/api/change-password',{method:'POST',body:JSON.stringify({oldPassword:String(d.get('currentPassword')||''),newPassword:String(d.get('newPassword')||'')})});form.reset();toast('Heslo bylo změněno.')}catch(err){toast(err.message,'error')}}

function renderStorageTab(){return '<section class="panel"><div class="panel-head"><div><h3>Zálohy Freezers ESPORT</h3><p>Záloha se stáhne zašifrovaná heslem, které zvolíš při exportu.</p></div></div><div class="github-status"><div class="status-indicator '+(state.github?'connected':'')+'"><span class="sync-light"></span>'+(API_BASE?'DATA V ZABEZPEČENÉ SLUŽBĚ':'LOKÁLNÍ NÁHLED')+'</div><div class="section-actions"><button class="btn btn-primary" data-action="export-data">↓ Stáhnout šifrovanou zálohu</button><label class="btn">Obnovit šifrovanou zálohu<input type="file" id="importFile" accept=".json,application/json" hidden></label></div><p class="field-hint">Bez hesla zálohu nelze obnovit.</p></div></section>'}
